export const curated2021FallSeeds: CuratedAnimeSeed[] = curated2021FallSeedRows.map((seed) => {
  const correctedOfficialSiteUrl = reviewedOfficialSiteUrlCorrections[seed.anilistId];
  if (!correctedOfficialSiteUrl) return seed;

  return {
    ...seed,
    officialSiteUrl: correctedOfficialSiteUrl,
    ...(seed.sourceReferenceUrls ? {
      sourceReferenceUrls: seed.sourceReferenceUrls.map((url) => (
        url === seed.officialSiteUrl ? correctedOfficialSiteUrl : url
      ))
    } : {})
  };
});

export const curated2021FallAnimeIds = curated2021FallSeeds.map(({ anilistId }) => anilistId);
